import{c as n,Q as r,J as e,h as l,k as t,m as i}from"./chunks/framework.WgZQdPFo.js";const v=JSON.parse('{"title":"Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости","description":"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор.","frontmatter":{"title":"Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости","description":"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор.","tags":["Экономика","Инструменты","Мастерская"],"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости"}],["meta",{"property":"og:description","content":"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор."}],["meta",{"property":"og:url","content":"https://omnicraft-erp.com/ru/articles/pricing-and-margins"}],["meta",{"property":"og:image","content":"https://omnicraft-erp.com/img/ru/front/calculator.webp"}],["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@graph\\": [\\n    {\\n      \\"@type\\": \\"WebApplication\\",\\n      \\"name\\": \\"Калькулятор наценки и маржи онлайн\\",\\n      \\"applicationCategory\\": \\"BusinessApplication\\",\\n      \\"operatingSystem\\": \\"All\\",\\n      \\"browserRequirements\\": \\"Requires JavaScript. Requires HTML5.\\",\\n      \\"offers\\": {\\n        \\"@type\\": \\"Offer\\",\\n        \\"price\\": \\"0\\",\\n        \\"priceCurrency\\": \\"RUB\\"\\n      },\\n      \\"description\\": \\"Практический онлайн-калькулятор торговой наценки, валовой маржи и розничной цены изделия от себестоимости для мастерских и штучного производства.\\"\\n    },\\n    {\\n      \\"@type\\": \\"Article\\",\\n      \\"headline\\": \\"Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости\\",\\n      \\"description\\": \\"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор.\\",\\n      \\"inLanguage\\": \\"ru-RU\\",\\n      \\"mainEntityOfPage\\": \\"https://omnicraft-erp.com/ru/articles/pricing-and-margins\\",\\n      \\"datePublished\\": \\"2026-10-10\\",\\n      \\"dateModified\\": \\"2026-10-15\\",\\n      \\"author\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"ОмниКрафт ЕРП\\",\\n        \\"url\\": \\"https://omnicraft-erp.com/ru/\\"\\n      },\\n      \\"publisher\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"ОмниКрафт ЕРП\\",\\n        \\"logo\\": {\\n          \\"@type\\": \\"ImageObject\\",\\n          \\"url\\": \\"https://omnicraft-erp.com/logo.svg\\"\\n        }\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"BreadcrumbList\\",\\n      \\"itemListElement\\": [\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 1,\\n          \\"name\\": \\"Главная\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 2,\\n          \\"name\\": \\"Статьи и руководства\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/articles/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 3,\\n          \\"name\\": \\"Ценообразование, наценка и маржа\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/articles/pricing-and-margins\\"\\n        }\\n      ]\\n    }\\n  ]\\n}\\n"]]},"headers":[],"relativePath":"ru/articles/pricing-and-margins.md","filePath":"ru/articles/pricing-and-margins.md"}'),o={name:"ru/articles/pricing-and-margins.md"};function c(p,a,d,h,m,u){const s=r("MarginCalculator");return e(),l("div",null,[a[0]||(a[0]=t('<div class="article-breadcrumb"><a href="/ru/articles/">← Все статьи и руководства</a></div><h1 id="ценообразование-наценка-и-маржа-как-рассчитать-цену-изделия-от-себестоимости" tabindex="-1">Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости <a class="header-anchor" href="#ценообразование-наценка-и-маржа-как-рассчитать-цену-изделия-от-себестоимости" aria-label="Permalink to &quot;Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости&quot;">​</a></h1><p>Один из самых коварных финансовых капканов для частного мастера или небольшой ремесленной мастерской — путаница между <strong>торговой наценкой</strong> и <strong>валовой маржой</strong>.</p><p>Нередка ситуация: мастер считает затраты на материалы и фурнитуру для кожаного портмоне — вышло 2 000 рублей. В голове возникает расчёт: <em>«Хочу заработать 40% прибыли. Сделаю наценку 40%: 2 000 × 1.4 = 2 800 рублей»</em>. Через месяц мастерская делает скидку постоянному клиенту в 30%, будучи уверенной, что 10% «маржи» всё ещё остаётся в кармане. В реальности заказ закрывается с чистым убытком.</p><p>В этой статье разберём математику ценообразования в производственной мастерской: формулы расчёта цены, фундаментальное отличие наценки от маржи, расчёт точки безубыточности и методику защиты своей прибыли.</p>',5)),i(s,{lang:"ru"}),a[1]||(a[1]=t('<hr><h2 id="наценка-и-маржа-в-чем-принципиальная-разница" tabindex="-1">Наценка и маржа: в чём принципиальная разница? <a class="header-anchor" href="#наценка-и-маржа-в-чем-принципиальная-разница" aria-label="Permalink to &quot;Наценка и маржа: в чём принципиальная разница?&quot;">​</a></h2><p>Многие начинающие предприниматели используют слова «наценка» и «маржа» как синонимы. Это грубая ошибка, приводящая к кассовым разрывам.</p><div class="price-breakdown-card"><div class="breakdown-header"><span class="breakdown-tag">Анатомия розничной цены</span><div class="breakdown-title">Структура выручки: себестоимость, маржа и наценка</div><p class="breakdown-desc">При себестоимости 60% от цены и наценке 66.7% итоговая валовая маржа составляет ровно 40%:</p></div><div class="breakdown-bar-track"><div class="breakdown-segment seg-cost" style="width:60%;background:#3b82f6;" data-tooltip="Себестоимость: 60% выручки (база 100%)"><span class="seg-label">Себестоимость: 60% выручки (База 100%)</span></div><div class="breakdown-segment seg-margin" style="width:40%;background:#10b981;" data-tooltip="Валовая маржа: 40% (наценка 66.7%)"><span class="seg-label">Валовая маржа: 40% (Наценка 66.7%)</span></div></div></div><h3 id="_1-торговая-наценка-markup" tabindex="-1">1. Торговая наценка (Markup) <a class="header-anchor" href="#_1-торговая-наценка-markup" aria-label="Permalink to &quot;1. Торговая наценка (Markup)&quot;">​</a></h3><p>Наценка показывает, <strong>на сколько процентов розничная цена выше себестоимости</strong>. Она отталкивается от затрат.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Формула наценки</span><div class="formula-heading">Торговая наценка от себестоимости (Markup %)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Наценка %</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Цена продажи</span> <span class="math-op">−</span> <span class="math-var">Себестоимость</span></span><span class="math-denom"><span class="math-var">Себестоимость</span></span></span><span class="math-op">×</span><span class="math-var">100%</span></div></div></div><ul><li><strong>Пределы:</strong> наценка может составлять 50%, 100%, 300% и более. Если себестоимость чехла для очков 500 рублей, а продаёте вы его за 1 500 рублей, ваша наценка составляет 200%.</li></ul><h3 id="_2-маржинальность-или-маржа-margin" tabindex="-1">2. Маржинальность или маржа (Margin) <a class="header-anchor" href="#_2-маржинальность-или-маржа-margin" aria-label="Permalink to &quot;2. Маржинальность или маржа (Margin)&quot;">​</a></h3><p>Маржа показывает, <strong>какую долю в итоговой выручке составляют «чистые» заработанные деньги</strong>. Она отталкивается от продажной цены.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Формула маржи</span><div class="formula-heading">Валовая маржинальность выручки (Margin %)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Маржа %</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Цена продажи</span> <span class="math-op">−</span> <span class="math-var">Себестоимость</span></span><span class="math-denom"><span class="math-var">Цена продажи</span></span></span><span class="math-op">×</span><span class="math-var">100%</span></div></div></div><ul><li><strong>Пределы:</strong> маржа <strong>никогда не может превышать 100%</strong>. Если изделие продано за 2 000 рублей, то даже при нулевой себестоимости маржа будет ровно 100%.</li></ul><h3 id="сравнительная-таблица-соответствия-наценки-и-маржи" tabindex="-1">Сравнительная таблица соответствия наценки и маржи <a class="header-anchor" href="#сравнительная-таблица-соответствия-наценки-и-маржи" aria-label="Permalink to &quot;Сравнительная таблица соответствия наценки и маржи&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Себестоимость (₽)</th><th style="text-align:center;">Желаемая маржа (%)</th><th style="text-align:center;">Необходимая наценка (%)</th><th style="text-align:center;">Розничная цена (₽)</th><th style="text-align:center;">Фактическая прибыль (₽)</th></tr></thead><tbody><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>20%</strong></td><td style="text-align:center;"><strong>25%</strong></td><td style="text-align:center;">1 250</td><td style="text-align:center;">250</td></tr><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>30%</strong></td><td style="text-align:center;"><strong>43%</strong></td><td style="text-align:center;">1 428</td><td style="text-align:center;">428</td></tr><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>40%</strong></td><td style="text-align:center;"><strong>67%</strong></td><td style="text-align:center;">1 667</td><td style="text-align:center;">667</td></tr><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>50%</strong></td><td style="text-align:center;"><strong>100%</strong></td><td style="text-align:center;">2 000</td><td style="text-align:center;">1 000</td></tr><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>60%</strong></td><td style="text-align:center;"><strong>150%</strong></td><td style="text-align:center;">2 500</td><td style="text-align:center;">1 500</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Внимание к опасности слепой скидки</p><p>Если вы хотите получить рентабельность продаж (маржу) 40%, вам необходимо делать наценку на себестоимость <strong>не 40%, а 67%</strong>. Если вы просто нацените 40%, ваша фактическая маржа составит всего 28.5%.</p></div><hr><h2 id="как-рассчитать-розничную-цену-зная-себестоимость-и-целевую-маржу" tabindex="-1">Как рассчитать розничную цену, зная себестоимость и целевую маржу <a class="header-anchor" href="#как-рассчитать-розничную-цену-зная-себестоимость-и-целевую-маржу" aria-label="Permalink to &quot;Как рассчитать розничную цену, зная себестоимость и целевую маржу&quot;">​</a></h2><p>Когда мастер определяет продажную стоимость изделия, правильный ход мысли — идти не от наценки, а от <strong>целевой рентабельности</strong>.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Инженерный расчёт</span><div class="formula-heading">Формула розничной цены от целевой маржинальности</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Цена продажи</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Полная себестоимость</span></span><span class="math-denom">1 <span class="math-op">−</span> <span class="math-fraction"><span class="math-num"><span class="math-var">Целевая маржа %</span></span><span class="math-denom">100</span></span></span></span></div></div></div><h4 id="пример-из-цеха" tabindex="-1">Пример из цеха: <a class="header-anchor" href="#пример-из-цеха" aria-label="Permalink to &quot;Пример из цеха:&quot;">​</a></h4><ul><li>Полная себестоимость ремня (кожа чепрак с учётом обрезков + пряжка + 2 часа работы мастера + износ инструмента) = <strong>2 400 ₽</strong>.</li><li>Мастерская стремится к маржинальности <strong>35%</strong> (чтобы покрывать аренду, налоги и откладывать на развитие).</li></ul><div class="formula-hero-card" style="margin:16px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Цена продажи</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">2 400</span><span class="math-denom">1 <span class="math-op">−</span> 0.35</span></span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">2 400</span><span class="math-denom">0.65</span></span><span class="math-op">≈</span><span class="math-var" style="color:#10b981;">3 690 ₽</span></div></div></div><p>Если бы мастер по ошибке просто прибавил 35% к себестоимости, цена составила бы $2400 \\times 1.35 = 3240$ ₽. Потеря на каждом ремне составила бы <strong>450 рублей</strong> чистой прибыли.</p><hr><h2 id="три-метода-ценообразования-в-ремесленном-производстве" tabindex="-1">Три метода ценообразования в ремесленном производстве <a class="header-anchor" href="#три-метода-ценообразования-в-ремесленном-производстве" aria-label="Permalink to &quot;Три метода ценообразования в ремесленном производстве&quot;">​</a></h2><p>На практике мастерские используют три базовых подхода к назначению цен:</p><h3 id="_1-затратныи-метод-«себестоимость-плюс»" tabindex="-1">1. Затратный метод («Себестоимость плюс») <a class="header-anchor" href="#_1-затратныи-метод-«себестоимость-плюс»" aria-label="Permalink to &quot;1. Затратный метод («Себестоимость плюс»)&quot;">​</a></h3><p>Классический инженерный подход. Вы суммируете все прямые затраты (материалы, полезный раскрой, фурнитуру), оплату труда мастера за затраченные часы, долю постоянных накладных расходов (аренда помещения, амортизация оборудования, расходники) и закладываете фиксированную норму прибыли.</p><ul><li><strong>Плюсы:</strong> гарантирует окупаемость каждого изделия и защиту от работы в минус.</li><li><strong>Минусы:</strong> не учитывает рыночный спрос и ценность авторского дизайна.</li></ul><h3 id="_2-рыночныи-метод-анализ-конкурентов" tabindex="-1">2. Рыночный метод (Анализ конкурентов) <a class="header-anchor" href="#_2-рыночныи-метод-анализ-конкурентов" aria-label="Permalink to &quot;2. Рыночный метод (Анализ конкурентов)&quot;">​</a></h3><p>Мастер изучает витрины ярмарок и социальных сетей других ремесленников схожего уровня и выставляет среднерыночную стоимость.</p><ul><li><strong>Опасность метода:</strong> конкурент может работать дома на старых складских запасах сырья без учёта стоимости своего труда. Слепое копирование чужих цен часто приводит к скрытым убыткам.</li></ul><h3 id="_3-ценностныи-метод-премиальное-ценообразование" tabindex="-1">3. Ценностный метод (Премиальное ценообразование) <a class="header-anchor" href="#_3-ценностныи-метод-премиальное-ценообразование" aria-label="Permalink to &quot;3. Ценностный метод (Премиальное ценообразование)&quot;">​</a></h3><p>Цена определяется не затратами материалов, а эмоциональной ценностью, статусностью, уникальностью ручной работы и качеством сервиса (подарочная упаковка, пожизненная гарантия на швы, индивидуальное тиснение).</p><ul><li><strong>Плюсы:</strong> максимальная маржа (от 60% до 80%).</li></ul><hr><h2 id="точка-безубыточности-мастерскои" tabindex="-1">Точка безубыточности мастерской <a class="header-anchor" href="#точка-безубыточности-мастерскои" aria-label="Permalink to &quot;Точка безубыточности мастерской&quot;">​</a></h2><p><strong>Точка безубыточности (Break-Even Point)</strong> — это объём продаж, при котором выручка мастерской в точности покрывает все постоянные и переменные расходы. Прибыль в этой точке равна нулю: мастерская не терпит убытков, но ещё ничего не заработала сверх расходов.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Финансовая модель</span><div class="formula-heading">Точка безубыточности мастерской (Break-Even Point)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Точка безубыточности (шт)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Постоянные расходы в месяц</span></span><span class="math-denom"><span class="math-var">Цена изделия</span> <span class="math-op">−</span> <span class="math-var">Переменная себестоимость</span></span></span></div></div></div><h4 id="пример" tabindex="-1">Пример: <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример:&quot;">​</a></h4><ul><li>Аренда мастерской, отопление и интернет: <strong>30 000 ₽/мес</strong>.</li><li>Розничная цена сумки: <strong>9 000 ₽</strong>.</li><li>Переменная себестоимость одной сумки (кожа, нитки, молния, фурнитура): <strong>4 000 ₽</strong>.</li><li>Маржинальный доход с одного изделия: $9000 - 4000 = 5000$ ₽.</li></ul><div class="formula-hero-card" style="margin:16px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Точка безубыточности</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">30 000</span><span class="math-denom">5 000</span></span><span class="math-op">=</span><span class="math-var" style="color:#10b981;">6 сумок в месяц</span></div></div></div><p>Первые 6 сумок каждого месяца работают исключительно на покрытие аренды и коммунальных счетов. И только начиная с 7-й сумки мастерская начинает формировать прибыль владельца.</p><hr><h2 id="с-чего-начать-точныи-расчет-базы" tabindex="-1">С чего начать: точный расчёт базы <a class="header-anchor" href="#с-чего-начать-точныи-расчет-базы" aria-label="Permalink to &quot;С чего начать: точный расчёт базы&quot;">​</a></h2><p>Невозможно выстроить надёжное ценообразование, если в фундаменте лежит неверная себестоимость: не учтены обрезки сырья, не оцифрована ставка собственного рабочего часа или забыта амортизация оборудования.</p><p>Воспользуйтесь нашим интерактивным инструментом для расчета реальной производственной базы:</p><div class="cta-calc-box"><div class="cta-calc-content"><h3>Рассчитайте точную себестоимость изделия онлайн</h3><p>Наш бесплатный калькулятор оцифрует потери сырья, брак, комплектующие, посчитает стоимость вашего часа работы и выдаст диагноз рентабельности заказа.</p><a href="/ru/calculators/product-cost-calculator" class="vp-button brand" data-omni-event="sat_pricing_cta_calc"> Перейти в калькулятор себестоимости → </a></div></div><hr><h2 id="связанные-статьи-производственного-кластера" tabindex="-1">Связанные статьи производственного кластера <a class="header-anchor" href="#связанные-статьи-производственного-кластера" aria-label="Permalink to &quot;Связанные статьи производственного кластера&quot;">​</a></h2><ul><li><a href="/ru/calculators/">Каталог онлайн-калькуляторов себестоимости «ОмниКрафт ЕРП»</a> — все специализированные отраслевые калькуляторы и готовые таблицы смет.</li><li><a href="/ru/calculators/product-cost-calculator">Универсальный калькулятор себестоимости продукции онлайн</a> — расчёт единицы товара, технологический брак и экспорт в Excel/LibreOffice.</li><li><a href="/ru/calculators/cake-cost-calculator">Калькулятор себестоимости торта онлайн</a> — расчёт ингредиентов брутто, упёка, крема и декора для кондитеров.</li><li><a href="/ru/calculators/leather-cost-calculator">Калькулятор себестоимости изделия из кожи онлайн</a> — раскрой шкуры, топография деталей и финансовые ловушки мастерской.</li><li><a href="/ru/calculators/3d-print-cost-calculator">Калькулятор себестоимости 3D-печати онлайн</a> — расход филамента и фотополимера, амортизация принтера и норма-час оператора.</li><li><a href="/ru/calculators/candle-cost-calculator">Калькулятор себестоимости свечей и диффузоров онлайн</a> — соевый воск, процент ввода ароматизатора, фитили и тара.</li><li><a href="/ru/calculators/dish-cost-calculator">Калькулятор себестоимости блюда и полуфабрикатов онлайн</a> — фудкост, уварка сырья брутто/нетто и упаковка для общепита.</li><li><a href="/ru/calculators/beauty-cost-calculator">Калькулятор себестоимости маникюра и бьюти-услуг онлайн</a> — одноразовые наборы, стерилизация по СанПиН и аренда кабинета.</li><li><a href="/ru/articles/cost-calculation-software">Программы для расчёта себестоимости: почему Excel и 1С не подходят малым мастерским</a> — честный обзор учётных систем для растущего производства.</li></ul>',51))])}const f=n(o,[["render",c]]);export{v as __pageData,f as default};
